import React from 'react';
import { MOCK_AGENTS } from '../constants';
import { Trophy, Star } from 'lucide-react';

const AgentPerformance: React.FC = () => {
  const sortedAgents = [...MOCK_AGENTS].sort((a, b) => b.salesVolume - a.salesVolume);

  return (
    <div className="bg-white rounded-2xl border border-luxe-beige shadow-sm p-6">
      <div className="flex justify-between items-center mb-6">
        <h3 className="font-serif text-xl">Top Performers</h3>
        <button className="text-sm text-luxe-teal hover:underline">View All</button>
      </div>

      <div className="space-y-5">
        {sortedAgents.map((agent, index) => (
          <div key={agent.id} className="flex items-center gap-4">
            <div className="relative">
              <img src={agent.avatar} alt={agent.name} className="w-12 h-12 rounded-full object-cover" />
              {index === 0 && (
                <div className="absolute -top-1 -right-1 bg-yellow-400 text-white p-0.5 rounded-full shadow-sm">
                  <Trophy size={10} fill="currentColor" />
                </div>
              )}
            </div>
            <div className="flex-1">
              <div className="flex justify-between items-center mb-1">
                <h4 className="font-medium text-luxe-charcoal">{agent.name}</h4>
                <span className="font-mono text-sm font-semibold">${(agent.salesVolume / 1000000).toFixed(1)}M</span>
              </div>
              <div className="flex justify-between items-center text-xs text-gray-500">
                <span>{agent.activeListings} Active Listings</span>
                <div className="flex items-center text-yellow-500">
                  <Star size={10} fill="currentColor" className="mr-0.5" />
                  <span>5.0</span>
