export enum PropertyStatus {
  ACTIVE = 'Active',
  PENDING = 'Pending',
  SOLD = 'Sold',
}

export interface Property {
  id: string;
  title: string;
  address: string;
  price: number;
  status: PropertyStatus;
  image: string;
  views: number;
  inquiries: number;
  daysOnMarket: number;
  agentId: string;
  coordinates: { x: number; y: number }; // For map visualization
  features?: string[];
  sqft?: number;
  beds?: number;
  baths?: number;
}

export interface Agent {
  id: string;
  name: string;
  avatar: string;
  salesVolume: number;
  activeListings: number;
}

export interface SalesFunnelData {
  stage: string;
  count: number;
  fill: string;
}

export interface AIRecommendation {
  id: string;
  type: 'pricing' | 'marketing' | 'content';
  title: string;
  description: string;
  impact: string; // e.g., "+12% visibility"
}

export interface MapZone {
