  name: string;
  demandLevel: number; // 0-100
  coordinates: { cx: number; cy: number; r: number };
  avgPrice?: number;
  trend?: string;
}

export interface Client {
  id: string;
  name: string;
  email: string;
  budget: number;
  stage: 'Lead' | 'Viewing' | 'Negotiation' | 'Closed';
  interestedIn: string; // Property ID reference
  lastContact: string;
  agentId: string;
  avatar: string;
}

export interface RevenueData {
  month: string;
  revenue: number;
  projected: number;
}

