import { GoogleGenAI, Type } from "@google/genai";
import { Property, AIRecommendation } from "../types";

// Initialize client
// Note: In a real app, ensure process.env.API_KEY is set.
// We assume the key is provided via environment variable.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateInsights = async (properties: Property[]): Promise<AIRecommendation[]> => {
  try {
    // Prepare a summary of the data for the prompt
    const portfolioSummary = properties.map(p => ({
      title: p.title,
      price: p.price,
      daysOnMarket: p.daysOnMarket,
      views: p.views,
      inquiries: p.inquiries,
      status: p.status
    }));

    const prompt = `
      You are an expert Real Estate Analyst AI for "EstateVision Pro".
      Analyze the following property portfolio data and provide 3 strategic, high-impact recommendations to sell these properties faster or at a better price.
      Focus on pricing adjustments, marketing focus, or content improvements based on views vs inquiries data.

      Portfolio Data:
      ${JSON.stringify(portfolioSummary, null, 2)}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING, enum: ['pricing', 'marketing', 'content'] },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              impact: { type: Type.STRING }
            },
            required: ['id', 'type', 'title', 'description', 'impact']
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIRecommendation[];
    }
    return [];
  } catch (error) {
    console.error("Error generating insights:", error);
    // Fallback mock data in case of API error (or missing key in demo)
    return [
      {
        id: 'err1',
        type: 'pricing',
        title: 'Price Adjustment Alert',
        description: 'High views but low inquiries on "Country Estate" suggest pricing may be 5-10% above market perception.',
        impact: 'Potential +15% Leads'
      },
      {
        id: 'err2',
        type: 'content',
        title: 'Visual Refresh Needed',
        description: 'Modern Loft has low engagement. Update listing with twilight photography to capture luxury appeal.',
        impact: '+20% CTR'
      },
      {
        id: 'err3',
        type: 'marketing',
        title: 'Targeted Campaign',
        description: 'The Penthouse is stalling. Launch a targeted LinkedIn campaign for finance professionals.',
        impact: 'High Value Prospecting'
      }
    ];
  }
};

