  const activeListings = MOCK_PROPERTIES.filter(p => p.status === 'Active').length;
  const totalViews = MOCK_PROPERTIES.reduce((acc, curr) => acc + curr.views, 0);
  const totalInquiries = MOCK_PROPERTIES.reduce((acc, curr) => acc + curr.inquiries, 0);

  return (
    <div className="p-4 lg:p-8 max-w-[1600px] mx-auto space-y-8 animate-fade-in">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl lg:text-4xl font-serif text-luxe-charcoal">Overview</h2>
          <p className="text-gray-500 mt-1">Welcome back, Alexandra. Market demand is up 12% today.</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => onNavigate('reports')}
            className="px-4 py-2 bg-white border border-luxe-beige rounded-lg text-sm font-medium hover:bg-luxe-light transition-colors"
          >
            View Reports
          </button>
          <button className="px-4 py-2 bg-luxe-charcoal text-white rounded-lg text-sm font-medium hover:bg-black transition-colors shadow-lg shadow-luxe-charcoal/20">
            Add Listing
