      {/* Top Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard 
          label="Total Active Listings" 
          value={activeListings} 
          trend={12} 
          icon={<Activity size={20} className="text-luxe-teal"/>}
        />
        <MetricCard 
          label="Portfolio Value" 
          value="$42.5M" 
          trend={5.4} 
          icon={<DollarSign size={20} className="text-luxe-teal"/>}
          dark
        />
        <MetricCard 
          label="Total Views" 
          value={totalViews.toLocaleString()} 
          trend={-2.1} 
          icon={<Eye size={20} className="text-luxe-teal"/>}
        />
