import React, { useState, useEffect } from 'react';
import { Sparkles, RefreshCw, TrendingUp, Tag, Image as ImageIcon } from 'lucide-react';
import { generateInsights } from '../services/geminiService';
import { Property, AIRecommendation } from '../types';

interface AIInsightsProps {
  properties: Property[];
}

const AIInsights: React.FC<AIInsightsProps> = ({ properties }) => {
  const [insights, setInsights] = useState<AIRecommendation[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasLoaded, setHasLoaded] = useState(false);

  const fetchInsights = async () => {
    setLoading(true);
    try {
      const recommendations = await generateInsights(properties);
      setInsights(recommendations);
      setHasLoaded(true);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // Auto-fetch on mount just for the demo experience
  useEffect(() => {
    if (!hasLoaded) fetchInsights();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const getIcon = (type: string) => {
    switch (type) {
      case 'pricing': return <Tag className="text-luxe-teal" />;
      case 'content': return <ImageIcon className="text-purple-500" />;
      case 'marketing': return <TrendingUp className="text-blue-500" />;
      default: return <Sparkles className="text-luxe-teal" />;
    }
  };

  return (
    <div className="bg-luxe-charcoal text-white rounded-2xl p-6 lg:p-8 relative overflow-hidden border border-gray-800 shadow-2xl">
      {/* Decor element */}
      <div className="absolute -top-20 -right-20 w-64 h-64 bg-luxe-teal/10 rounded-full blur-3xl pointer-events-none"></div>

      <div className="flex justify-between items-center mb-8 relative z-10">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Sparkles size={18} className="text-luxe-teal" />
            <h2 className="text-luxe-teal font-mono text-xs uppercase tracking-widest">Gemini Intelligence</h2>
          </div>
          <h3 className="font-serif text-2xl lg:text-3xl">Portfolio Advisor</h3>
        </div>
        <button 
          onClick={fetchInsights}
          disabled={loading}
          className="p-2 hover:bg-white/10 rounded-full transition-colors disabled:opacity-50"
        >
          <RefreshCw size={20} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className="grid gap-4 relative z-10">
        {loading ? (
          <div className="space-y-3">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-24 bg-white/5 rounded-xl animate-pulse"></div>
            ))}
          </div>
        ) : (
          insights.map((insight) => (
            <div key={insight.id} className="bg-white/5 hover:bg-white/10 border border-white/5 hover:border-luxe-teal/30 p-4 rounded-xl transition-all duration-300 group cursor-pointer">
              <div className="flex gap-4">
                <div className="mt-1 p-2 rounded-lg bg-black/30 h-fit">
                  {getIcon(insight.type)}
                </div>
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-1">
                    <h4 className="font-medium text-lg group-hover:text-luxe-teal transition-colors">{insight.title}</h4>
                    <span className="text-xs font-mono text-luxe-teal bg-luxe-teal/10 px-2 py-1 rounded border border-luxe-teal/20">
                      {insight.impact}
                    </span>
                  </div>
                  <p className="text-gray-400 text-sm leading-relaxed">{insight.description}</p>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {!loading && insights.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          No insights available. Try refreshing.
        </div>
      )}
    </div>
  );
};

export default AIInsights;

